// capability_tools.go — the describe_source MCP tool: the operable capability
// description for an integration target (Epic #726 / #738).
//
// One tool covers both lines: pass subject_kind="provider" (ref = provider name)
// or subject_kind="data_source" (ref = source id or name). The description is
// the "how do I drive this" document — named operations (or the source's usable
// scope), limits, and worked examples — generated by the server from the
// CONFIRMED contract / source metadata. It is read-only: there is no parameter
// that accepts description text, so the tool cannot be used to author or edit a
// description.
package main

import (
	"context"
	"net/url"
	"strings"

	"github.com/mark3labs/mcp-go/mcp"
	"github.com/mark3labs/mcp-go/server"
)

// newDescribeSourceTool builds the describe_source tool. Split out from
// registration so a test can assert its input surface is read-only.
func newDescribeSourceTool() mcp.Tool {
	return mcp.NewTool("describe_source",
		mcp.WithDescription("Get an operable capability description for a configured external API provider OR data source: what it is for, how to call it (which tool + argument shape), its operations (for a provider) or usable scope (for a data source), the limits that apply, and worked task examples. Use this to learn how to drive a source without reading its docs. Read-only: the description is generated by the server from the confirmed integration contract and cannot be edited by a caller.\n\nAfter onboarding a new source, call this (or get_provider_schema / list_data_sources, which also carry the description) before your first call."),
		mcp.WithString("subject_kind",
			mcp.Description("What to describe: 'provider' (an external API) or 'data_source' (a queryable data source)."),
			mcp.Required(),
			mcp.Enum("provider", "data_source"),
		),
		mcp.WithString("ref",
			mcp.Description("The target reference: a provider name (e.g. 'serp-api'), or a data source id or name (e.g. 'analytics')."),
			mcp.Required(),
		),
	)
}

func registerCapabilityTools(s *server.MCPServer, api *apiClient) {
	s.AddTool(
		newDescribeSourceTool(),
		func(ctx context.Context, req mcp.CallToolRequest) (*mcp.CallToolResult, error) {
			args := req.GetArguments()
			kind, errRes := requireString(args, "subject_kind")
			if errRes != nil {
				return errRes, nil
			}
			ref, errRes := requireString(args, "ref")
			if errRes != nil {
				return errRes, nil
			}
			path := "/mcp/capabilities/" + url.PathEscape(strings.ToLower(kind)) + "/" + url.PathEscape(ref)
			data, err := api.get(path)
			if err != nil {
				return mcp.NewToolResultError(err.Error()), nil
			}
			return mcp.NewToolResultText(string(data)), nil
		},
	)
}
